/* Decorative, conceptual 8085 data flow; not a CPU timing simulation. */
(()=>{
const layer=document.createElement('div');layer.className='processor-background';layer.setAttribute('aria-hidden','true');
const wires=['M0 340 H140 V450 H240','M240 510 H120 V680 H0','M400 450 H530 V350 H1080 V420 H1240','M400 510 H500 V720 H1180 V540 H1240','M1400 450 H1500 V280 H1600','M1400 510 H1470 V700 H1600','M320 390 V240 H610 V0','M320 570 V810 H580 V1000','M1320 390 V110 H1100 V0','M1320 570 V830 H1000 V1000'];
const pins=Array.from({length:8},(_,i)=>{const y=411+i*19;return `<path class="circuit-wire" d="M224 ${y}h16 M400 ${y}h16 M1224 ${y}h16 M1400 ${y}h16"/>`;}).join('');
layer.innerHTML=`<svg viewBox="0 0 1600 1000" preserveAspectRatio="xMidYMid slice" focusable="false"><defs><pattern id="circuitDots" width="32" height="32" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8" fill="#728bac"/></pattern></defs><rect class="circuit-grid" width="1600" height="1000" fill="url(#circuitDots)"/>${wires.map((d,i)=>`<path class="circuit-wire" d="${d}"/><path class="data-pulse p${i%3+1}" d="${d}"/>`).join('')}${pins}<rect class="bg-chip-core" x="240" y="390" width="160" height="180" rx="13"/><text class="bg-small" x="269" y="431">MICROPROCESSOR</text><text class="bg-chip-number" x="266" y="493">8085</text><text class="bg-small" id="demoInstruction" x="263" y="535">MVI A, 05H</text><rect class="bg-component" x="1240" y="390" width="160" height="180" rx="13"/><text class="bg-label" x="1262" y="426">REGISTERS</text><rect class="bg-component" x="1262" y="441" width="116" height="34" rx="4"/><text class="bg-label" id="demoAlu" x="1272" y="464">ALU READY</text><text class="bg-small" id="demoRegisters" x="1260" y="503">A:00H  B:00H</text><text class="bg-small" id="demoFlags" x="1260" y="536">CY:0 Z:0 P:0</text><circle class="bg-node" cx="140" cy="340" r="4"/><circle class="bg-node" cx="530" cy="350" r="4"/><circle class="bg-node" cx="1180" cy="720" r="4"/><circle class="bg-node" cx="1470" cy="700" r="4"/><text class="bg-small" x="95" y="321">DATA BUS</text><text class="bg-small" x="1398" y="733">ADDRESS BUS</text></svg><div class="math-note n1"><span>ARITHMETIC / ADD</span>0000 1111<br>+ 0000 0001<br>───────────<br>0001 0000</div><div class="math-note n2"><span>FETCH → DECODE → EXECUTE</span>MVI A, 05H<br>MVI B, 03H<br>ADD B → A = 08H</div><div class="math-note n3"><span>BITWISE / XOR</span>1100 ⊕ 1010 = 0110<br>A ← A XOR B</div><div class="math-note n4"><span>CARRY / 8-BIT ADDITION</span>FFH + 01H = 00H<br>CY = 1 · Z = 1</div><div class="bg-caption">8085 / INSTRUCTION DEMO · ILLUSTRATIVE TIMING</div>`;
const svg=layer.querySelector('svg');
svg.insertAdjacentHTML('beforeend',`<rect class="demo-memory" x="207" y="640" width="230" height="102" rx="9"/><text class="bg-small" x="225" y="664">PROGRAM MEMORY</text><text class="demo-value" id="demoMemory" x="225" y="689">0200H · MVI A, 05H</text><text class="bg-small" id="demoPc" x="225" y="719">PC → 0200H</text><path class="circuit-wire" d="M320 640V570"/><path class="data-pulse" d="M320 640V570"/><g class="stage-lights"><rect data-stage="0" x="210" y="305" width="70" height="28" rx="5"/><rect data-stage="1" x="285" y="305" width="70" height="28" rx="5"/><rect data-stage="2" x="360" y="305" width="80" height="28" rx="5"/><text x="220" y="323">FETCH</text><text x="294" y="323">DECODE</text><text x="369" y="323">EXECUTE</text></g><rect class="demo-memory" x="1205" y="640" width="230" height="102" rx="9"/><text class="bg-small" x="1223" y="664">ACCUMULATOR / A</text><text class="demo-value" id="demoBinary" x="1223" y="694">0000 0000</text><text class="bg-small" id="demoStatus" x="1223" y="721">FETCHING INSTRUCTION</text><path class="circuit-wire" d="M1320 570V640"/><path class="data-pulse p3" d="M1320 570V640"/><circle class="chip-halo" cx="320" cy="480" r="122"/><circle class="chip-halo second" cx="1320" cy="480" r="117"/>`);
document.body.prepend(layer);
const toggle=document.createElement('button');toggle.id='motionToggle';toggle.type='button';document.querySelector('.bottom-actions').insertBefore(toggle,document.getElementById('showDetails'));
const preference=window.matchMedia('(prefers-reduced-motion: reduce)');let running=!preference.matches;
function update(){document.body.classList.toggle('motion-running',running);toggle.textContent=running?'Pause motion':'Play motion';toggle.setAttribute('aria-label',running?'Pause decorative background animation':'Play decorative background animation');toggle.setAttribute('aria-pressed',String(running));toggle.disabled=preference.matches;if(preference.matches){toggle.textContent='Motion off';toggle.title='Reduced motion is enabled in your device settings.';}}
toggle.addEventListener('click',()=>{running=!running;update();});preference.addEventListener('change',()=>{running=!preference.matches;toggle.title='';update();});document.addEventListener('visibilitychange',()=>{document.body.classList.toggle('motion-running',running&&!document.hidden);});update();
// A repeating three-instruction example, independent of the user's calculation.
const program=[{pc:'0200H',next:'0202H',code:'MVI A, 05H',a:5,b:0,alu:'LOAD A'},{pc:'0202H',next:'0204H',code:'MVI B, 03H',a:5,b:3,alu:'LOAD B'},{pc:'0204H',next:'0205H',code:'ADD B',a:8,b:3,alu:'05 + 03'}];
let tick=0,timer=null;const label=(id,text)=>layer.querySelector('#'+id).textContent=text;
function step(){const index=Math.floor(tick/3)%3,phase=tick%3,p=program[index];
 if(tick%9===0){label('demoRegisters','A:00H  B:00H');label('demoBinary','0000 0000');label('demoFlags','CY:0 Z:0 P:0');}
 layer.querySelectorAll('[data-stage]').forEach(el=>el.classList.toggle('active',+el.dataset.stage===phase));layer.classList.toggle('alu-active',phase===2);
 label('demoInstruction',p.code);label('demoMemory',p.pc+' · '+p.code);label('demoPc','PC → '+(phase===2?p.next:p.pc));label('demoStatus',['FETCHING OPCODE','DECODING '+p.code,'WRITING RESULT'][phase]);label('demoAlu',phase===2?p.alu:'ALU READY');
 if(phase===2){label('demoRegisters','A:0'+p.a+'H  B:0'+p.b+'H');label('demoBinary',p.a.toString(2).padStart(8,'0').replace(/(.{4})/g,'$1 ').trim());}
 tick=(tick+1)%9;
}
function syncMotion(){if(timer){clearInterval(timer);timer=null;}if(document.body.classList.contains('motion-running')&&!document.hidden)timer=setInterval(step,1600);}
step();new MutationObserver(syncMotion).observe(document.body,{attributes:true,attributeFilter:['class']});syncMotion();
})();
